<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\ApiKeyClient\Application\Policy\Allow;

use Throwable;
use Civi\Lughauth\Features\Access\ApiKeyClient\Application\Usecase\Create\ApiKeyClientCreateAllowDecision;
use Civi\Lughauth\Features\Access\ApiKeyClient\Application\Usecase\Update\ApiKeyClientUpdateAllowDecision;
use Civi\Lughauth\Features\Access\ApiKeyClient\Application\Usecase\List\ApiKeyClientListAllowDecision;
use Civi\Lughauth\Features\Access\ApiKeyClient\Application\Usecase\Retrieve\ApiKeyClientRetrieveAllowDecision;
use Civi\Lughauth\Features\Access\ApiKeyClient\Application\Usecase\Delete\ApiKeyClientDeleteAllowDecision;
use Civi\Lughauth\Features\Access\ApiKeyClient\Application\Usecase\Enable\ApiKeyClientEnableAllowDecision;
use Civi\Lughauth\Features\Access\ApiKeyClient\Application\Usecase\Disable\ApiKeyClientDisableAllowDecision;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Security\AllowDecision;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class OnlyForRootAllow
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(private readonly Context $context)
    {
    }
    public function checkCreate(ApiKeyClientCreateAllowDecision $proposal): AllowDecision
    {
        return $this->check('ApiKeyClientCreateAllowDecision', $proposal);
    }
    public function checkUpdate(ApiKeyClientUpdateAllowDecision $proposal): AllowDecision
    {
        return $this->check('ApiKeyClientUpdateAllowDecision', $proposal);
    }
    public function checkList(ApiKeyClientListAllowDecision $proposal): AllowDecision
    {
        return $this->check('ApiKeyClientListAllowDecision', $proposal);
    }
    public function checkRetrieve(ApiKeyClientRetrieveAllowDecision $proposal): AllowDecision
    {
        return $this->check('ApiKeyClientRetrieveAllowDecision', $proposal);
    }
    public function checkDelete(ApiKeyClientDeleteAllowDecision $proposal): AllowDecision
    {
        return $this->check('ApiKeyClientDeleteAllowDecision', $proposal);
    }
    public function checkEnable(ApiKeyClientEnableAllowDecision $proposal): AllowDecision
    {
        return $this->check('ApiKeyClientEnableAllowDecision', $proposal);
    }
    public function checkDisable(ApiKeyClientDisableAllowDecision $proposal): AllowDecision
    {
        return $this->check('ApiKeyClientDisableAllowDecision', $proposal);
    }
    private function check(string $name, AllowDecision $proposal): AllowDecision
    {
        $this->logDebug("Check " . $name . " on OnlyForRootAllow Api key client");
        $span = $this->startSpan("Check " + name + " on OnlyForRootAllow Api key client");
        try {
            $identity = $this->context->getIdentity();
            if ($proposal->isAllowed()) {
                if (!(($identity->hasScope("platform:global_access") && $identity->hasRole("admin")))) {
                    $proposal->deny('Disabled if not OnlyForRoot');
                }
            }
            return $proposal;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
